<script setup>
import { computed, onMounted, ref } from 'vue'
import { Download, Plus, RefreshCw, Search, Trash2 } from '@lucide/vue'
import { UnifiedQueryDateRange } from '@mohe/unified-query-vue3'
import FundPlatformStoreScopePicker from './components/FundPlatformStoreScopePicker.vue'
const params=new URLSearchParams(location.search); const platform=params.get('source')==='platform'; const prefix=platform?'/adminapi/fund':'/storeapi/fund';
const active=ref('entry'), subjects=ref([]), documents=ref([]), ledgerRows=ref([]), ledgerOpening=ref(null), reportRows=ref([]), reportSummary=ref(null), message=ref(''), loading=ref(false), entryModalOpen=ref(false)
const platformStoreId=ref(0), platformScopeTree=ref([]), platformScopeLoading=ref(false)
const dateValue=(date)=>`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`
const today=()=>dateValue(new Date())
const monthStart=()=>{const date=new Date();date.setDate(1);return dateValue(date)}
const filters=ref({date_from:monthStart(),date_to:today(),store_id:'',direction:'',document_status:''})
const ledgerFilters=ref({date_from:monthStart(),date_to:today(),subject_type:'NORMAL'})
const reportFilters=ref({date_from:monthStart(),date_to:today(),subject_id:'',subject_type:''})
const documentsPage=ref(1), documentsLimit=ref(10), documentsCount=ref(0)
const ledgerPage=ref(1), ledgerLimit=ref(10)
const appliedDocumentFilters=ref(null)
const documentsPages=computed(()=>Math.max(1,Math.ceil(documentsCount.value/documentsLimit.value)))
const documentRange=computed(()=>({min:filters.value.date_from,max:filters.value.date_to}))
const ledgerRange=computed(()=>({min:ledgerFilters.value.date_from,max:ledgerFilters.value.date_to}))
const reportRange=computed(()=>({min:reportFilters.value.date_from,max:reportFilters.value.date_to}))
// 模板传入的 ref 已自动解包；只更新当前视图草稿条件，点击查询后才刷新结果。
function applyDateRange(target,{min,max}){target.date_from=min;target.date_to=max}
const form=ref(blank())
function blank(){return {id:0,store_id:'',business_date:today(),direction:'EXPENSE',summary:'',remark:'',lines:[{subject_id:'',amount:'',summary:'',remark:''}]}}
function cookie(name){const matched=document.cookie.match(new RegExp(`(?:^|;\\s*)${name}=([^;]*)`));return matched?decodeURIComponent(matched[1]).trim():''}
function token(){return platform?cookie('admin-token'):sessionStorage.getItem('cashier-v3:session-token')||sessionStorage.getItem('fund-v3-token')||localStorage.getItem('token')||''}
async function requestUrl(url,options={}){const headers={Accept:'application/json',...(options.body?{'Content-Type':'application/json'}:{}),...(token()?{'Authori-zation':`Bearer ${token()}`}:{})};const r=await fetch(url,{credentials:platform?'same-origin':'omit',...options,headers});const b=await r.json();if(!r.ok||Number(b.status)!==200)throw Error(b.msg||'请求失败');return b.data}
async function api(path='',options={}){return requestUrl(prefix+path,options)}
async function downloadFile(path){const r=await fetch(prefix+path,{credentials:platform?'same-origin':'omit',headers:token()?{'Authori-zation':`Bearer ${token()}`}:{}});if(!r.ok){let message='Excel 文件下载失败，请稍后重试。';try{message=(await r.json()).msg||message}catch(e){}throw Error(message)}return r.blob()}
function amount(cents){return (Number(cents||0)/100).toFixed(2)}
async function loadSubjects(){subjects.value=await api('/subjects'+(platform?'?include_disabled=1':''))}
async function loadPlatformScope(){if(!platform)return;platformScopeLoading.value=true;try{platformScopeTree.value=(await api('/scope')).tree||[]}catch(e){message.value=e.message}finally{platformScopeLoading.value=false}}
function requirePlatformStore(){if(!platform||platformStoreId.value>0)return true;message.value='请选择一个门店后查询。';return false}
function scopedFilters(value){return platform?{...value,store_id:platformStoreId.value}:value}
function scopedPath(path){if(!platform)return path;return path+(path.includes('?')?'&':'?')+'store_id='+platformStoreId.value}
// 单据列表使用服务端分页；总数来自同一权限和筛选条件，不以当前页行数推算。
async function loadDocuments(){if(!requirePlatformStore()){documents.value=[];documentsCount.value=0;appliedDocumentFilters.value=null;return}loading.value=true;try{if(!appliedDocumentFilters.value)appliedDocumentFilters.value=scopedFilters({...filters.value});const query={...appliedDocumentFilters.value,page:documentsPage.value,limit:documentsLimit.value};const data=await api('/documents?'+new URLSearchParams(query));documentsCount.value=Number(data.count)||0;if(documentsPage.value>documentsPages.value){documentsPage.value=documentsPages.value;return await loadDocuments()}documents.value=data.list||[]}catch(e){message.value=e.message}finally{loading.value=false}}
function searchDocuments(){if(!requirePlatformStore())return;appliedDocumentFilters.value=scopedFilters({...filters.value});documentsPage.value=1;return loadDocuments()}
function changeDocumentPage(page){if(page<1||page>documentsPages.value||loading.value)return;documentsPage.value=page;loadDocuments()}
function changeDocumentLimit(){documentsPage.value=1;loadDocuments()}
// A fresh authorized ledger result starts at page one; the API still supplies every running balance.
async function loadLedger(){ledgerPage.value=1;if(!requirePlatformStore()){ledgerRows.value=[];ledgerOpening.value=null;return}const data=await api('/ledger?'+new URLSearchParams(scopedFilters(ledgerFilters.value)));ledgerRows.value=data.list||[];ledgerOpening.value=ledgerFilters.value.date_from?{id:'opening',business_date:ledgerFilters.value.date_from,opening_balance:data.opening_balance}:null}
async function loadReport(){if(!requirePlatformStore()){reportRows.value=[];reportSummary.value=null;return}const data=await api('/report?'+new URLSearchParams(scopedFilters(reportFilters.value)));reportRows.value=data.list||[];reportSummary.value=data.summary||null}
async function openTab(tab){active.value=tab;message.value='';if(tab==='ledger')await loadLedger();else if(tab==='report')await loadReport();else if(tab==='entry')await loadDocuments();else if(tab==='settings')await loadSubjects()}
const ledgerPages=computed(()=>Math.max(1,Math.ceil(ledgerRows.value.length/ledgerLimit.value)))
// The API supplies running balances for the full authorized result; pagination only hides rows.
// The opening balance is context, not a transaction, so it appears only on page one.
const ledgerDisplayRows=computed(()=>{
  const start=(ledgerPage.value-1)*ledgerLimit.value
  const rows=ledgerRows.value.slice(start,start+ledgerLimit.value)
  return ledgerPage.value===1&&ledgerOpening.value?[ledgerOpening.value,...rows]:rows
})
function changeLedgerPage(page){if(page<1||page>ledgerPages.value)return;ledgerPage.value=page}
function changeLedgerLimit(){ledgerPage.value=1}
function selectLedgerSubjectType(type){ledgerFilters.value.subject_type=type;loadLedger()}
async function exportData(kind){if(!requirePlatformStore())return;try{const filters=kind==='ledger'?ledgerFilters.value:reportFilters.value;const result=await api(`/${kind}/export?`+new URLSearchParams(scopedFilters(filters)));const fileKey=String(result.file_key||result.fileKey||'');if(!fileKey)throw Error('Excel 文件生成失败，请稍后重试。');const blob=await downloadFile(`/export-files/${encodeURIComponent(fileKey)}`);const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=result.filename||'费用数据.xlsx';link.click();URL.revokeObjectURL(url);message.value='Excel 文件已开始下载。'}catch(e){message.value=e.message}}
function addLine(){form.value.lines.push({subject_id:'',amount:'',summary:'',remark:''})} function removeLine(i){if(form.value.lines.length>1)form.value.lines.splice(i,1)}
function newDocument(){if(!requirePlatformStore())return;form.value=blank();if(platform)form.value.store_id=platformStoreId.value;entryModalOpen.value=true}
async function edit(row){const d=await api(scopedPath('/documents/'+row.id));form.value={...d,lines:d.lines.map(x=>({...x,amount:amount(x.amount_cents)}))};entryModalOpen.value=true}
async function save(){if(!requirePlatformStore())return;try{const body={...form.value,store_id:platform?platformStoreId.value:form.value.store_id,lines:form.value.lines.map(x=>({...x,subject_id:Number(x.subject_id),amount_cents:Math.round(Number(x.amount)*100)}))};await api('/documents',{method:'POST',body:JSON.stringify(body)});message.value='收支单已保存为未审核。';entryModalOpen.value=false;form.value=blank();await loadDocuments()}catch(e){message.value=e.message}}
// 审核或撤销成功后清除上次失败提示，并重新读取服务端单据状态；不在页面伪造审核结果。
async function audit(row,audited){try{await api(`/documents/${row.id}/audit`,{method:'POST',body:JSON.stringify({audited,store_id:platformStoreId.value})});message.value='';await loadDocuments()}catch(e){message.value=e.message}}
// 删除不在浏览器直接移除行；确认并由服务端核对未审核状态后，重新读取分页及总数。
async function deleteDraft(row){if(!confirm('删除这张未审核收支单？'))return;try{await api(`/documents/${row.id}`,{method:'DELETE'});message.value='';await loadDocuments()}catch(e){message.value=e.message}}
async function reverse(row){if(!confirm('将生成一张已审核的反向冲销单，继续？'))return;try{await api(`/documents/${row.id}/reverse`,{method:'POST',body:JSON.stringify({store_id:platformStoreId.value})});await loadDocuments()}catch(e){message.value=e.message}}
function addSubject(){if(subjects.value.some(subject=>!subject.id)){message.value='请先保存当前新增科目。';return}subjects.value.push({id:0,subject_code:'',subject_name:'',subject_type:'NORMAL',sort_order:0,is_enabled:1})}
async function saveSubject(subject){try{await api('/subjects',{method:'POST',body:JSON.stringify(subject)});await loadSubjects()}catch(e){message.value=e.message}}
onMounted(async()=>{try{await loadSubjects();if(platform)await loadPlatformScope();else await loadDocuments()}catch(e){message.value=e.message}})
</script>
<template><main class="fund"><header class="top"><div><h1>费用</h1><p>审核后的收支单才进入台账和统计；撤销审核后立即不生效。</p></div><button class="btn light" @click="openTab(active)"><RefreshCw :size="15"/> 刷新</button></header><div class="tabs"><button :class="{active:active==='entry'}" @click="openTab('entry')">收支单录入</button><button :class="{active:active==='ledger'}" @click="openTab('ledger')">收支台账</button><button :class="{active:active==='report'}" @click="openTab('report')">费用统计与专项报表</button><button v-if="platform" :class="{active:active==='settings'}" @click="openTab('settings')">其他设置</button></div><div v-if="message" class="message">{{message}}</div>
<section v-if="active==='entry'" class="panel"><div class="filters filter-bar"><FundPlatformStoreScopePicker v-if="platform" v-model="platformStoreId" :tree="platformScopeTree" :loading="platformScopeLoading"/><div class="fund-period-picker"><UnifiedQueryDateRange :model-value="documentRange" :allow-clear="false" label="收支单查询周期" @change="applyDateRange(filters,$event)"/></div><label class="field inline-field"><span>方向</span><select v-model="filters.direction"><option value="">全部</option><option value="INCOME">收入</option><option value="EXPENSE">支出</option></select></label><label class="field inline-field"><span>状态</span><select v-model="filters.document_status"><option value="">全部</option><option value="DRAFT">未审核</option><option value="APPROVED">已审核</option></select></label><button class="btn filter-submit" @click="searchDocuments"><Search :size="16"/> 查询</button><button class="btn filter-submit" @click="newDocument"><Plus :size="15"/> 新增收支单</button></div><div class="table-wrap"><table class="table"><thead><tr><th v-if="platform">门店</th><th>日期</th><th>单号</th><th>方向</th><th>金额</th><th>摘要</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="r in documents" :key="r.id"><td v-if="platform">{{r.store_name||r.store_id}}</td><td>{{r.business_date}}</td><td>{{r.document_no}}</td><td>{{r.direction==='INCOME'?'收入':'支出'}}</td><td>{{r.amount}}</td><td>{{r.summary}}</td><td><span class="tag">{{r.document_status==='APPROVED'?'已审核':'未审核'}}</span></td><td><!-- 门店只开放未审核编辑；平台既有入口不在本轮变更范围。 --><button v-if="platform||r.document_status==='DRAFT'" class="btn light" @click="edit(r)">编辑</button> <button v-if="r.document_status==='DRAFT'" class="btn" @click="audit(r,true)">审核</button><button v-else class="btn light" @click="audit(r,false)">撤销审核</button> <button v-if="!platform&&r.document_status==='DRAFT'" class="btn danger" title="删除未审核收支单" aria-label="删除未审核收支单" @click="deleteDraft(r)">删除</button> <!-- 门店移除冲销入口；平台冲销入口及历史关联不在本轮变更范围。 --><button v-if="platform&&r.document_status==='APPROVED'" class="btn danger" @click="reverse(r)">冲销</button></td></tr><tr v-if="!loading&&!documents.length"><td :colspan="platform?8:7" class="table-empty">暂无符合条件的收支单</td></tr></tbody></table></div><footer class="fund-pagination"><span>共 {{documentsCount}} 条，第 {{documentsPage}} / {{documentsPages}} 页</span><label>每页 <select v-model.number="documentsLimit" aria-label="每页条数" @change="changeDocumentLimit"><option :value="10">10</option><option :value="20">20</option><option :value="50">50</option><option :value="100">100</option></select> 条</label><button class="btn light" :disabled="loading||documentsPage<=1" @click="changeDocumentPage(documentsPage-1)">上一页</button><button class="btn light" :disabled="loading||documentsPage>=documentsPages" @click="changeDocumentPage(documentsPage+1)">下一页</button></footer></section><div v-if="entryModalOpen" class="modal-mask" @click.self="entryModalOpen=false"><section class="modal"><header><h2>{{form.id?'编辑收支单':'新增收支单'}}</h2><button class="icon-btn" title="关闭" @click="entryModalOpen=false">×</button></header><div class="form-grid"><label class="field" v-if="platform">门店 ID<input v-model="form.store_id" inputmode="numeric" placeholder="平台录入必填" readonly/></label><label class="field">业务日期<input v-model="form.business_date" type="date"/></label><label class="field">收支方向<select v-model="form.direction"><option value="INCOME">收入</option><option value="EXPENSE">支出</option></select></label><label class="field wide">摘要<input v-model="form.summary" placeholder="例如：8 月团建聚餐"/></label><label class="field wide">备注<textarea v-model="form.remark" rows="2"/></label></div><div class="line" v-for="(line,i) in form.lines" :key="i"><select v-model="line.subject_id"><option value="">费用科目/专项</option><option v-for="s in subjects.filter(x=>x.is_enabled||x.id===line.subject_id)" :value="s.id">{{s.subject_name}}</option></select><input v-model="line.amount" inputmode="decimal" placeholder="金额"/><input v-model="line.summary" placeholder="明细摘要"/><input v-model="line.remark" placeholder="明细备注"/><button class="btn danger" :title="'删除第 '+(i+1)+' 条'" @click="removeLine(i)"><Trash2 :size="15"/></button></div><footer><button class="btn light" @click="addLine"><Plus :size="15"/> 增加明细</button><span></span><button class="btn light" @click="entryModalOpen=false">取消</button><button class="btn" @click="save">保存未审核单据</button></footer></section></div>
<section v-if="active==='ledger'" class="panel"><div class="filters filter-bar ledger-filters"><FundPlatformStoreScopePicker v-if="platform" v-model="platformStoreId" :tree="platformScopeTree" :loading="platformScopeLoading"/><div class="fund-period-picker"><UnifiedQueryDateRange :model-value="ledgerRange" :allow-clear="false" label="收支台账查询周期" @change="applyDateRange(ledgerFilters,$event)"/></div><div class="field inline-field"><span>类型</span><div class="segment-control" role="group" aria-label="费用类型"><button :class="{active:ledgerFilters.subject_type==='NORMAL'}" @click="selectLedgerSubjectType('NORMAL')">普通费用</button><button :class="{active:ledgerFilters.subject_type==='SPECIAL'}" @click="selectLedgerSubjectType('SPECIAL')">团建费</button></div></div><button class="btn filter-submit" @click="loadLedger"><Search :size="16"/> 查询</button><button class="btn light filter-export" @click="exportData('ledger')"><Download :size="16"/> 导出</button></div><div class="table-wrap"><table class="table"><thead><tr><th>门店</th><th>日期</th><th>单号</th><th>科目</th><th>方向</th><th>金额</th><th>余额</th><th>摘要</th></tr></thead><tbody><tr v-for="r in ledgerDisplayRows" :key="r.id"><td>{{r.id==='opening'?'-':r.store_name||r.store_id}}</td><td>{{r.business_date}}</td><td>{{r.id==='opening'?'-':r.document_no}}</td><td>{{r.id==='opening'?'-':r.subject_name_snapshot}}</td><td>{{r.id==='opening'?'期初':r.direction==='INCOME'?'收入':'支出'}}</td><td :class="r.id==='opening'?'muted':r.direction==='INCOME'?'positive':'negative'">{{r.id==='opening'?'-':r.signed_amount}}</td><td>{{r.id==='opening'?r.opening_balance:r.balance}}</td><td>{{r.id==='opening'?'-':r.summary}}</td></tr></tbody></table></div><footer class="fund-pagination"><span>共 {{ledgerRows.length}} 条，第 {{ledgerPage}} / {{ledgerPages}} 页</span><label>每页 <select v-model.number="ledgerLimit" aria-label="台账每页条数" @change="changeLedgerLimit"><option :value="10">10</option><option :value="20">20</option><option :value="50">50</option><option :value="100">100</option></select> 条</label><button class="btn light" :disabled="ledgerPage<=1" @click="changeLedgerPage(ledgerPage-1)">上一页</button><button class="btn light" :disabled="ledgerPage>=ledgerPages" @click="changeLedgerPage(ledgerPage+1)">下一页</button></footer></section>
<section v-if="active==='report'" class="panel"><div class="filter-bar report-filter-bar"><FundPlatformStoreScopePicker v-if="platform" v-model="platformStoreId" :tree="platformScopeTree" :loading="platformScopeLoading"/><div class="fund-period-picker"><UnifiedQueryDateRange :model-value="reportRange" :allow-clear="false" label="费用统计查询周期" @change="applyDateRange(reportFilters,$event)"/></div><label class="field inline-field"><span>科目</span><select v-model="reportFilters.subject_id"><option value="">全部科目</option><option v-for="subject in subjects" :key="subject.id" :value="subject.id">{{subject.subject_name}}</option></select></label><label class="field inline-field"><span>类型</span><select v-model="reportFilters.subject_type"><option value="">全部类型</option><option value="NORMAL">普通费用</option><option value="SPECIAL">团建费</option></select></label><button class="btn filter-submit" @click="loadReport"><Search :size="16"/> 查询</button><button class="btn light filter-export" @click="exportData('report')"><Download :size="16"/> 导出</button></div><div class="table-wrap"><table class="table"><thead><tr><th>门店</th><th>科目</th><th>类型</th><th>收入</th><th>支出</th><th>净额</th><th>明细数</th></tr></thead><tbody><tr v-for="r in reportRows" :key="r.subject_id"><td>{{r.store_name||r.store_id}}</td><td>{{r.subject_name_snapshot}}</td><td>{{r.subject_type_snapshot==='SPECIAL'?'团建费':'普通费用'}}</td><td class="positive">{{r.income_amount}}</td><td class="negative">{{r.expense_amount}}</td><td :class="Number(r.net_amount_cents)>=0?'positive':'negative'">{{r.net_amount}}</td><td>{{r.line_count}}</td></tr></tbody><tfoot v-if="reportSummary"><tr><td>-</td><td>合计</td><td>-</td><td class="positive">{{reportSummary.income_amount}}</td><td class="negative">{{reportSummary.expense_amount}}</td><td :class="Number(reportSummary.net_amount_cents)>=0?'positive':'negative'">{{reportSummary.net_amount}}</td><td>{{reportSummary.line_count}}</td></tr></tfoot></table></div></section>
<section v-if="active==='settings'" class="panel settings"><div class="section-head"><h2>其他设置</h2><button class="btn" @click="addSubject"><Plus :size="15"/> 新增科目</button></div><p class="muted">平台统一维护费用科目与专项；停用后不得新录入，历史单据继续按发生时快照展示。</p><table class="table"><thead><tr><th>编码</th><th>名称</th><th>类型</th><th>排序</th><th>启用</th><th></th></tr></thead><tbody><tr v-for="s in subjects" :key="s.id||'new'"><td><input v-model="s.subject_code"/></td><td><input v-model="s.subject_name"/></td><td><select v-model="s.subject_type"><option value="NORMAL">普通费用</option><option value="SPECIAL">专项</option></select></td><td><input v-model="s.sort_order" type="number"/></td><td><input v-model="s.is_enabled" type="checkbox" :true-value="1" :false-value="0"/></td><td><button class="btn light" @click="saveSubject(s)">保存</button></td></tr></tbody></table></section></main></template>
